es\",\"desc\":\"Clubes deportivos, grupos artísticos y actividades recreativas\",\"btn_texto\":\"Conocer Más\",\"imagen\":\"img/bienestar_estudiantil_1.png\",\"imagen_fija\":false}],\"div_serv1\":\"\",\"div_servicios_lista\":\"\",\"etiqueta_superior\":\"Servicios Institucionales\",\"titulo\":\"Todo lo que necesitas en  *un solo lugar*\",\"serv1_imagen\":\"img/1788754247_1720017362_dbe7fc57cd0d7d9ab805.jpg\",\"serv2_titulo\":\"Campus Virtual\",\"serv2_desc\":\"Plataforma educativa 24/7\",\"serv2_imagen\":\"img/servicio-campus.jpg\",\"serv3_titulo\":\"Horarios\",\"serv3_desc\":\"Consulta tus horarios de clase\",\"serv3_imagen\":\"img/salud.jpg\",\"serv4_titulo\":\"Servicios Digitales\",\"serv4_desc\":\"Trámites en línea y gestión académica\",\"serv4_imagen\":\"img/salud.jpg\",\"serv5_titulo\":\"Podcast ITB\",\"serv5_desc\":\"Escucha nuestro contenido educativo\",\"serv5_imagen\":\"img/salud.jpg\",\"serv6_titulo\":\"Arte y Deportes\",\"serv6_desc\":\"Clubes deportivos, grupos artísticos y actividades recreativas\",\"serv6_imagen\":\"img/estudiantes1.png\"},\"alianzas\":{\"_visible\":\"1\",\"titulo\":\"Alianzas del ITB\",\"boton_todas\":\"Ver Alianzas y Convenios\",\"lista_logos\":[{\"imagen\":\"img/aecd83a071c09531ceea048d412d09e6.png\",\"nombre\":\"Aliado 1\"},{\"imagen\":\"img/alianza_2.jpg\",\"nombre\":\"Aliado 2\"},{\"imagen\":\"img/alianza_3.png\",\"nombre\":\"Aliado 3\"},{\"imagen\":\"img/alianza_4.png\",\"nombre\":\"Aliado 4\"},{\"imagen\":\"img/alianza_5.png\",\"nombre\":\"Aliado 5\"}],\"lista_fotos\":[{\"imagen\":\"img/alianza_sub1.png\",\"nombre\":\"Actividad ITB 1\"},{\"imagen\":\"img/alianza_sub2.png\",\"nombre\":\"Actividad ITB 2\"},{\"imagen\":\"img/alianza_sub3.png\",\"nombre\":\"Actividad ITB 3\"},{\"imagen\":\"img/alianza_sub4.png\",\"nombre\":\"Actividad ITB 4\"},{\"imagen\":\"img/alianza_sub5.png\",\"nombre\":\"Actividad ITB 5\"},{\"imagen\":\"img/alianza_sub6.png\",\"nombre\":\"Actividad ITB 6\"}],\"div_textos\":\"\",\"div_logos\":\"\",\"div_fotos\":\"\"},\"sobre_cogobierno\":{\"_visible\":\"1\",\"titulo\":\"Co Gobierno\",\"descripcion\":\"Representantes de la comunidad académica que participan activamente en la toma de decisiones e institucionalidad del ITB\",\"miembros\":[{\"foto\":\"img/a91dff1fd95b4e6d0d6e68c5388c927b.jpg\",\"nombre\":\"Obst. Lenny Mariscal San Martín\",\"cargo\":\"Representante de Docentes\"},{\"foto\":\"img/8974ecdec40ba06bcf640706e7a7ae12.jpg\",\"nombre\":\"Ing. Marcos Escaleras Gómez\",\"cargo\":\"Representante de Trabajadores\"}],\"div_estructura\":\"\",\"card_imagen\":\"img/86d94af61b878d428da1c96394fcb831.jpg\",\"card_icono\":\"\",\"card_titulo\":\"Estructura Orgánica\",\"card_descripcion\":\"Conoce la jerarquía, áreas académicas y departamentos administrativos que conforman el ITB.\",\"card_boton\":\"Ver Organigrama\",\"card_boton_url\":\"#\"},\"himno\":{\"_visible\":\"1\",\"div_textos\":\"\",\"titulo\":\"Música y letra\",\"descripcion\":\"Nuestro himno representa la historia, los valores y el espíritu de excelencia de la comunidad bolivariana. Acompaña cada uno de nuestros actos solemnes y nos identifica como líderes tecnológicos en el país.\",\"div_letra\":\"\",\"autor\":\"Dr. Narcilo Natan\\r\\nVillavicencio Maldonado\",\"coro\":\"Juventud estudiosa presente\\r\\nahora y siempre por la patria inmortal\\r\\nel futuro nos grita más fuerte:\\r\\n¡Bolivarianos estudiar es triunfar!\\r\\nel futuro nos grita más fuerte:\\r\\n¡Bolivarianos estudiar es triunfar!\\r\\nel bienestar de la sociedad.\",\"estrofa1\":\"Nuestra patria reclama el progreso\\r\\ny el progreso será realidad\\r\\nsi estudiamos con fe y más esfuerzo\\r\\ncon ahínco, con pasión y voluntad\",\"estrofa2\":\"Adelante que el triunfo ya es nuestro\\r\\ndios nos guía en nuestro caminar\\r\\nadelante valor... triunfaremos\\r\\n¡Bolivarianos estudiar es triunfar!\\r\\nadelante valor... triunfaremos\\r\\n¡Bolivarianos estudiar es triunfar!\",\"div_multimedia\":\"\",\"audio\":\"audio/himnoitb.mp3\",\"btn_descargar\":\"Descargar música\",\"imagen\":\"img/Himno_Estudiante_itb.jpg\",\"nota_legal\":\"Estos archivos son para uso exclusivo del usuario final. Por favor, no los redistribuya\\r\\nsin el permiso del coro de ITB.\"}},\"updated_at\":\"2026-09-12 01:19:44\"}', '2026-09-18 09:39:12'),
('_paginas_creadas', 'pg_7716650bace6', '{\"id\":\"pg_7716650bace6\",\"nombre\":\"prueba1\",\"slug\":\"prueba1\",\"icon\":\"bi bi-award-fill\",\"menu_pos\":\"padre\",\"secciones\":[\"sobre_hero\",\"mision_vision\",\"autoridades\",\"himno\",\"alianzas\"],\"contenido\":{\"autoridades\":{\"_visible\":\"1\",\"etiqueta_superior\":\"Nuestro Equipo\",\"titulo\":\"Nuestras Autoridades\",\"descripcion\":\"Profesionales comprometidos con la excelencia académica, la innovación educativa y la gestión transparente de nuestra comunidad universitaria.\",\"boton_directorio\":\"Ver Directorio\",\"info_gestion\":\"\",\"div_global\":\"\",\"btn_directorio\":\"Ver Directorio\",\"subtitulo\":\"Profesionales comprometidos con la excelencia académica, la innovación educativa y la gestión transparente de nuestra comunidad universitaria.\",\"aut1_foto\":\"img/PHD.Roberto_tolozano.jpg\",\"aut1_nombre\":\"PhD. Roberto Tolozano Benites\",\"aut1_cargo\":\"Canciller\",\"aut1_email\":\"#\",\"aut1_telf\":\"#\",\"aut2_foto\":\"img/PHD.Elena_Tolozano.jpg\",\"aut2_nombre\":\"PhD. Elena Tolozano Benites\",\"aut2_cargo\":\"Rectora\",\"aut2_email\":\"#\",\"aut2_telf\":\"#\",\"aut3_foto\":\"img/PHD.Luis_alzate.jpg\",\"aut3_nombre\":\"PhD. Luis Alzate Peralta\",\"aut3_cargo\":\"Vicerrector Académico y de Investigación\",\"aut3_email\":\"#\",\"aut3_telf\":\"#\",\"aut4_foto\":\"img/PHD.Michelle_tolozano.webp\",\"aut4_nombre\":\"PhD. Michelle Tolozano Lapierre\",\"aut4_cargo\":\"Vicerrectora de Extensión y Gestión Administrativa\",\"aut4_email\":\"#\",\"aut4_telf\":\"#\"},\"alianzas\":{\"_visible\":\"1\",\"titulo\":\"Alianzas del ITB\",\"boton_todas\":\"Ver Alianzas y Convenios\",\"lista_logos\":[{\"imagen\":\"img/aecd83a071c09531ceea048d412d09e6.png\",\"nombre\":\"Aliado 1\"},{\"imagen\":\"img/alianza_2.jpg\",\"nombre\":\"Aliado 2\"},{\"imagen\":\"img/alianza_3.png\",\"nombre\":\"Aliado 3\"},{\"imagen\":\"img/alianza_4.png\",\"nombre\":\"Aliado 4\"},{\"imagen\":\"img/alianza_5.png\",\"nombre\":\"Aliado 5\"}]