('noticias', 'eventos', '[{\"categoria\":\"Evento\",\"fecha\":\"15 Sep 2025\",\"titulo\":\"¡METAMORFOSIS CREATIVA está por comenzar!\",\"descripcion\":\"Lo mejor del Diseño de Modas y Maquillaje...\",\"imagen\":\"img/noticia_1.png\"},{\"categoria\":\"Evento\",\"fecha\":\"12 Agt 2026\",\"titulo\":\"Estudiantes de Marketing Digital y Redes Sociales presentan proyectos novedosos en Elevator Pitch\",\"descripcion\":\"Una jornada académica que reunió a 21 mini agencias conformadas por estudiantes de la carrera Técnico Superior en Marketing Digital y Redes Sociales, quienes presentaron propuestas estratégicas y creativas para diferentes marcas y negocios.\",\"imagen\":\"img/7706394bfe67bfced3f1464e086011eb.jpg\"},{\"categoria\":\"Noticia\",\"fecha\":\"18 Ago.\",\"titulo\":\"ITB promovió una movilidad responsable durante la jornada “Guayaquil Camina Seguro”\",\"descripcion\":\"Una jornada orientada a fortalecer la educación y concienciación sobre la importancia de una movilidad segura, sostenible e incluyente.\",\"imagen\":\"img/noticia_camina_seguro.jpeg\"},{\"categoria\":\"Noticia\",\"fecha\":\"14 Ago.\",\"titulo\":\"ITB presentó proyectos de investigación e innovación aplicada en la Feria Agroazucar\",\"descripcion\":\"Cuatro proyectos desarrollados desde las facultades FACES y FATV se presentaron en la Feria Agroazucar.\",\"imagen\":\"img/noticia_feria_agroazucar.jpeg\"}]', '2026-09-18 09:39:12'),
