('sobre_mision', '_visible', '1', '2026-09-18 09:39:12'),
('sobre_mision', 'descripcion', 'Somos una Institución de Educación Superior comprometida con la excelencia académica y la formación de profesionales tecnológicos innovadores.', '2026-09-18 09:39:12'),
('sobre_mision', 'imagen', 'img/6722e39fdc881aa2a5155f2761551c00.jpg', '2026-09-18 09:39:12'),
('sobre_mision', 'puntos', '[{\"texto\":\"Autonomía de pensamiento y liderazgo.\"},{\"texto\":\"Aliado estratégico de empresas e instituciones.\"},{\"texto\":\"Formación práctica orientada al desarrollo económico y social.\"}]', '2026-09-18 09:39:12'),
('sobre_mision', 'titulo', 'Nuestra misión', '2026-09-18 09:39:12'),
('sobre_valores', '_visible', '1', '2026-09-18 09:39:12'),
('sobre_valores', 'etiqueta_superior', 'NUESTROS PRINCIPIOS Y VALORES', '2026-09-18 09:39:12'),
('sobre_valores', 'items', '[{\"icono\":\"img/c2bfa7c423adcd2d8b2f04fcea0a4f78.svg\",\"titulo\":\"Cogobierno\",\"descripcion\":\"Participación y gestión democrática\"},{\"icono\":\"img/f85372445ff70bd838ecb51f47294030.svg\",\"titulo\":\"Igualdad\",\"descripcion\":\"Oportunidades sin discriminación\"},{\"icono\":\"img/1870e3b99207af610588a15e8c564b66.svg\",\"titulo\":\"Calidad\",\"descripcion\":\"Excelencia en educación superior\"},{\"icono\":\"img/135639f1bc8e047730e524fad7040ebc.svg\",\"titulo\":\"Pertinencia\",\"descripcion\":\"Programas alineados a la sociedad\"},{\"icono\":\"img/ee1ecfe29ff4e6f05c5ddc7707199b0d.svg\",\"titulo\":\"Integralidad\",\"descripcion\":\"Formación académica y humana\"}]', '2026-09-18 09:39:12'),
('sobre_valores', 'titulo', 'Los pilares que guían la excelencia académica y humana en el ITB.', '2026-09-18 09:39:12'),
('sobre_vision', '_visible', '1', '2026-09-18 09:39:12'),
('sobre_vision', 'descripcion', 'Ser una institución de futuro, acreditada internacionalmente, que lidere la formación tecnológica en el Ecuador.', '2026-09-18 09:39:12'),
('sobre_vision', 'imagen', 'img/9bd0a3e3159e32a41e17a2fdc48caa55.jpg', '2026-09-18 09:39:12'),
('sobre_vision', 'puntos', '[{\"texto\":\"Liderazgo en educación tecnológica universitaria.\"},{\"texto\":\"Alianzas e integración con instituciones nacionales e internacionales.\"},{\"texto\":\"Transferencia tecnológica e innovación para el aprendizaje continuo.\"}]', '2026-09-18 09:39:12'),
('sobre_vision', 'titulo', 'Nuestra visión', '2026-09-18 09:39:12'),
('testimonios', '_visible', '1', '2026-09-18 09:39:12'),
('testimonios', 'div_global', '', '2026-09-18 09:39:12'),
('testimonios', 'div_testimonio', '', '2026-09-18 09:39:12'),
('testimonios', 'etiqueta_superior', 'HISTORIAS DE ÉXITO', '2026-09-18 09:39:12'),
('testimonios', 'info_testimonios', '', '2026-09-18 09:39:12'),
('testimonios', 'lista_testimonios', '[{\"imagen\":\"img/MariaFernanda.png\",\"cita\":\"\\\"El ITB me brindó las herramientas y el conocimiento necesario para destacarme en el campo laboral. Los docentes y el enfoque práctico marcaron la diferencia en mi formación profesional. Hoy lidero un equipo de trabajo gracias a la preparación que recibí.\\\"\",\"rol\":\"Graduada\",\"nombre\":\"María Fernanda López\",\"carrera\":\"Graduada en Enfermería - Promoción 2022\"},{\"imagen\":\"img/8a568c0257127dd19236f871a537a0bd.jpg\",\"cita\":\"\\\"La formación práctica y los proyectos reales que desarrollamos en clase me permitieron llegar a mi primera entrevista con un portafolio sólido. Hoy trabajo en el área que elegí desde el primer semestre.\\\"\",\"rol\":\"Graduado\",\"nombre\":\"Juan Perez Goya\",\"carrera\":\"Graduado en Desarrollo de Software\"},{\"imagen\":\"img/38f08960fc8ca02a6b4061c526c46759.jpg\",\"cita\":\"\\\"Lo que más valoro del ITB es la cercanía de los docentes: siempre hubo alguien dispuesto a resolver una duda o revisar un proyecto. Esa guía marcó la diferencia en mi formación.\\\"\",\"rol\":\"Graduada\",\"nombre\":\"Elena Fernandez Macias\",\"carrera\":\"Graduada en Marketing Digital\"},{\"imagen\":\"img/85dc8355286c1581b342d9b4220b5de6.jpg\",\"cita\":\"\\\"Estudiar y trabajar al mismo tiempo era mi mayor preocupación. Los horarios flexibles me permitieron avanzar sin dejar mi empleo, y hoy aplico a diario lo que aprendí en los talleres.\\\"\",\"rol\":\"Graduado\",\"nombre\":\"Francisco Arias Morales\",\"carrera\":\"Graduado en Gastronomía\"}]', '2026-09-18 09:39:12'),
('testimonios', 'titulo', 'Lo que dicen nuestros Graduados', '2026-09-18 09:39:12'),
('trayectoria', '_visible', '1', '2026-09-18 09:39:12'),
